import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Task structure simplification — FR 3.6.1 / 3.6.2","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-structure-simplification/spec.md","filePath":"feature/content-task-workflow/task-structure-simplification/spec.md"}'),n={name:"feature/content-task-workflow/task-structure-simplification/spec.md"};function s(o,e,l,c,p,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="task-structure-simplification-—-fr-3-6-1-3-6-2" tabindex="-1">Task structure simplification — FR 3.6.1 / 3.6.2 <a class="header-anchor" href="#task-structure-simplification-—-fr-3-6-1-3-6-2" aria-label="Permalink to &quot;Task structure simplification — FR 3.6.1 / 3.6.2&quot;">​</a></h1><p>User approved implementation 2026-10-17. Supersedes QC/planned-publication clauses of the earlier Task detail/five-state specs for this slice.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Keep dueDate, workflowRevision, description, references, Creator assignment and optional Client approval.</li><li>Remove plannedPublishAt from Task entity, workflow payloads, autosave and UI. Publishing remains a separate module.</li><li>No new QC assignment/cross-review. Reject non-null QC assignment from old clients instead of silently ignoring it.</li><li>States remain TODO, IN_PROGRESS, IN_REVIEW, FINISHED, CANCELLED. Keep reviewStep distinct; new approval contract is Manager then Client if required. No approval implementation in this slice.</li><li>Preserve CAS, membership rules, deadline bounds, explicit Creator start, Manager lock after first start, Campaign completion lock and Client access to all Workspace Tasks.</li><li>Keep historical QC/read-compatible legacy enum values and fields in existing documents until separately reviewed. Never reinterpret an ongoing QC round or delete task_approvals.</li><li>Do not change comments, POST/content entities or snapshot implementation.</li><li>Use existing UI controls/theme; no new locale keys required when removing controls; preserve historical translations. Light/dark and keyboard patterns unchanged.</li></ul><h2 id="migration-policy" tabindex="-1">Migration policy <a class="header-anchor" href="#migration-policy" aria-label="Permalink to &quot;Migration policy&quot;">​</a></h2><p>Forward-only metadata migration, default DRY_RUN, explicit APPLY flag. Remove obsolete plannedPublishAt validation dependency; preserve unrelated validator rules and all documents. Physical cleanup/backfill of old fields or states requires a separate allowlist decision. No automatic Atlas APPLY or init.</p>',6)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
